package com.optarena.orders;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class OrderServiceHiddenTest {
    @Test
    public void handlesNullGiftMessage() {
        OrderService svc = new OrderService();
        Order order = new Order("Bob", null);
        assertEquals("Gift note: (none)", svc.describeGift(order));
    }

    @Test
    public void trimsNonNullGiftMessage() {
        OrderService svc = new OrderService();
        Order order = new Order("Bob", "  Happy birthday!  ");
        assertEquals("Gift note: Happy birthday!", svc.describeGift(order));
    }
}

